import{_ as t,o as e,c as o,a0 as p}from"./chunks/framework.IrjkP_YN.js";const h=JSON.parse('{"title":"我抓到一次 AI 编的出处，而且那两句诗是真的","description":"","frontmatter":{},"headers":[],"relativePath":"posts/hallucination.md","filePath":"posts/hallucination.md","lastUpdated":null}'),r={name:"posts/hallucination.md"};function l(i,a,n,u,c,d){return e(),o("div",null,[...a[0]||(a[0]=[p('<h1 id="我抓到一次-ai-编的出处-而且那两句诗是真的" tabindex="-1">我抓到一次 AI 编的出处，而且那两句诗是真的 <a class="header-anchor" href="#我抓到一次-ai-编的出处-而且那两句诗是真的" aria-label="Permalink to &quot;我抓到一次 AI 编的出处，而且那两句诗是真的&quot;">​</a></h1><p>2026-09</p><h2 id="事情经过" tabindex="-1">事情经过 <a class="header-anchor" href="#事情经过" aria-label="Permalink to &quot;事情经过&quot;">​</a></h2><p>我在练手写 agent 循环，就是不用框架那个 <code>create_agent</code>，自己拿消息列表撸。做了个假的诗词检索工具，写死返回三首，李白《静夜思》、陈子昂《登幽州台歌》、李商隐《夜雨寄北》。</p><p>然后我给模型一个需求，姓张，男孩，五行缺水，想起个有志向的名字。</p><p>它调了工具，拿到了那三首，然后给我生成名字，出处写的是岑参&quot;瀚海阑干百丈冰&quot;，苏轼&quot;大江东去，浪淘尽&quot;。</p><h2 id="我第一反应不是生气-是去查" tabindex="-1">我第一反应不是生气，是去查 <a class="header-anchor" href="#我第一反应不是生气-是去查" aria-label="Permalink to &quot;我第一反应不是生气，是去查&quot;">​</a></h2><p>因为这两句我看着眼熟。</p><p>查完了，两句都是真的。瀚海阑干百丈冰，愁云惨淡万里凝，是岑参《白雪歌送武判官归京》。大江东去，浪淘尽，千古风流人物，是苏轼《念奴娇·赤壁怀古》。</p><p>那一刻我才反应过来这事有多麻烦。</p><p>要是它编的是&quot;李白《某某某》：床前明月光第二版&quot;，我一眼就看出来了。但它编的是两句真诗，只是不在我的库里。用户拿去查，查得到，写得还挺漂亮，谁能看出来是编的。</p><h2 id="我系统提示里明明写了" tabindex="-1">我系统提示里明明写了 <a class="header-anchor" href="#我系统提示里明明写了" aria-label="Permalink to &quot;我系统提示里明明写了&quot;">​</a></h2><p>原来那个项目的系统提示里就有一句&quot;必须引用检索结果&quot;。写着呢，照样被违反。</p><p>所以在提示词里要求模型别乱来这件事，基本等于没做。它是软约束，模型这次听下次不一定听，而且你没法知道它哪次没听。</p><p>还有个更细的。我写的是&quot;必须引用检索结果&quot;，但必须引用 A 不等于只能引用 A。按字面意思它引用了 A 之后再补两句 B，一点没违规。</p><p>后来我把这句改成了排他的说法。</p><h2 id="那怎么办" tabindex="-1">那怎么办 <a class="header-anchor" href="#那怎么办" aria-label="Permalink to &quot;那怎么办&quot;">​</a></h2><p>我的办法有点笨，但有效，就是能查的别让模型说。</p><p>具体到商标那条线，我做的事是模型不许输出法条原文，它只能输出一个数字，条款在数据库里的主键 id。代码拿着这个数字回数据库把原文取出来，拼进返回结果。</p><p>这样它连改一个字的机会都没有。</p><p>这个比&quot;让模型输出原文、然后代码去核对它抄得对不对&quot;要狠一层。核对的话你还得处理差一个字算不算对、全角半角括号算不算一样这些破事，而且核对逻辑自己也可能写错。不让它碰就没这些问题了。</p><p>至于诗词出处那一格，我暂时还没想到同样干净的办法。现在的处理是工具没返回东西、或者返回了但模型没用上，那一格就必须是 <code>null</code>，schema 里写死了。至少它不能假装自己用了检索结果。</p><h2 id="一个副产品" tabindex="-1">一个副产品 <a class="header-anchor" href="#一个副产品" aria-label="Permalink to &quot;一个副产品&quot;">​</a></h2><p>那次之后我养成个习惯，凡是模型说的、而我库里有的，我都回表查一遍再显示。</p><p>不是因为不信任它，是因为&quot;看起来对&quot;和&quot;对&quot;之间的差距用户看不出来，而我看得出来，只要我去查。</p><p>还有一条是我从这件事里学的，比技术细节值钱：<strong>被静默忽略的参数，比报错的参数危险。</strong></p><p>同一个项目里我还试过 <code>tool_choice=&#39;required&#39;</code>，就是强制模型必须调工具。DeepSeek 上它好像被忽略了，模型照样返回纯文本反问，<code>tool_calls</code> 是空的。它不报错，就是不干活。我一开始还误读成&quot;强制了它也会反问&quot;，是翻日志才发现根本没强制上。</p><p>报错的东西你会去修，不报错的东西你会以为它在工作。</p><hr><p>那三首假诗后来换成了真的 Milvus 检索，67,591 条向量。但这件事跟检索质量没关系，跟模型会不会编有关系，换了真数据它照样能编。</p>',30)])])}const q=t(r,[["render",l]]);export{h as __pageData,q as default};
